package com.spms.service;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import com.spms.dto.Dtos;import com.spms.entity.*;import com.spms.repository.*;import java.time.*;import java.util.*;@Service @RequiredArgsConstructor public class PayrollService{private final PayrollRepository repo;private final EmployeeRepository employees;public List<PayrollRecord> forEmployee(UUID id,boolean publishedOnly){return publishedOnly?repo.findByEmployeeIdAndStatusOrderByPayPeriodDesc(id,PayrollRecord.Status.PUBLISHED):repo.findByEmployeeIdOrderByPayPeriodDesc(id);}public PayrollRecord save(UUID id,Dtos.PayrollRequest r){var period=r.payPeriod().withDayOfMonth(1);var p=repo.findByEmployeeIdAndPayPeriod(id,period).orElseGet(PayrollRecord::new);var gross=r.basicPay().add(r.allowances());if(r.deductions().compareTo(gross)>0)throw new IllegalArgumentException("Deductions cannot exceed gross pay");p.setEmployee(employees.findById(id).orElseThrow());p.setPayPeriod(period);p.setBasicPay(r.basicPay());p.setAllowances(r.allowances());p.setDeductions(r.deductions());p.setNetPay(gross.subtract(r.deductions()));if(r.publish()){p.setStatus(PayrollRecord.Status.PUBLISHED);p.setPublishedAt(LocalDateTime.now());}return repo.save(p);}}
